#include <bits/stdc++.h>
using namespace std;

int main() {
    vector<int> v;
    v.reserve(10);                               // capacity >= 10, size == 0
    for (int i = 1; i <= 5; i++) v.push_back(i * 10);   // 10 20 30 40 50
    v.insert(v.begin() + 1, 15);                 // 10 15 20 30 40 50
    v.erase(v.begin() + 3, v.begin() + 5);       // usuwa 30 i 40 -> 10 15 20 50
    vector<int> w = {1, 2};
    v.insert(v.end(), w.begin(), w.end());       // doklejenie: 10 15 20 50 1 2
    erase_if(v, [](int x) { return x < 10; });   // C++20: 10 15 20 50
    cout << v.size() << ' ' << v.front() << ' ' << v.back() << '\n';   // 4 10 50

    vector<pair<int, int>> e;
    e.emplace_back(3, 4);                        // buduje pair(3, 4) w miejscu
    auto& [a, b] = e.back();
    cout << a + b << '\n';                       // 7

    try {
        cout << v.at(100) << '\n';
    } catch (const out_of_range&) {
        cout << "poza zakresem\n";
    }
    v.assign(3, 0);                              // 0 0 0
    for (int x : v) cout << x << ' ';
    cout << '\n';
}

