int main() {
    string s = "  Ala ma kota, kot ma Ale.  ";
    size_t a = s.find_first_not_of(' '), b = s.find_last_not_of(' ');
    s = s.substr(a, b - a + 1);                 // obcięte spacje: "Ala ma kota, kot ma Ale."
    for (size_t p = s.find("ma"); p != string::npos; p = s.find("ma", p + 1))
