    s.insert(0, ">> ");
    s.erase(s.size() - 1);                      // usuwa kropkę
    cout << s << '\n';                          // >> Ola ma kota, kot ma Ale
    cout << s.starts_with(">>") << s.ends_with("Ale") << '\n';   // 11 (C++20)
    erase(s, ' ');                              // C++20: usuwa wszystkie spacje
    cout << s << ' ' << s.size() << '\n';       // >>Olamakota,kotmaAle 20
    string_view sv = s;
    sv.remove_prefix(2);                        // O(1), bez kopiowania
