using namespace std;

int main() {
    set<int> s = {5, 1, 9, 3};
    auto [it, ok] = s.insert(3);                 // już jest: ok == false
    cout << ok << ' ' << *it << '\n';            // 0 3
    s.insert(s.end(), 12);                       // z podpowiedzią (dane rosnące)
    cout << *s.lower_bound(4) << ' ' << *s.upper_bound(9) << '\n';   // 5 12
    auto ub = s.upper_bound(8);                  // poprzednik 8: największy <= 8
    if (ub != s.begin()) cout << *prev(ub) << '\n';                 // 5
    s.erase(s.lower_bound(2), s.upper_bound(6)); // usuwa 3 i 5
    cout << s.contains(5) << ' ' << s.size() << '\n';               // 0 3

    multiset<int> ms = {2, 2, 2, 7};
    ms.erase(ms.find(2));                        // jedna kopia
    cout << ms.count(2) << '\n';                 // 2
    auto [l, r] = ms.equal_range(2);
    cout << distance(l, r) << '\n';              // 2
    ms.erase(2);                                 // wszystkie kopie
    cout << ms.size() << '\n';                   // 1

    set<int> t = {100, 1};
    s.merge(t);                                  // 1 już jest w s, więc zostaje w t
    for (int x : s) cout << x << ' ';            // 1 9 12 100
    cout << "| " << t.size() << '\n';            // | 1
    erase_if(s, [](int x) { return x > 50; });   // C++20
    cout << *s.rbegin() << '\n';                 // 12
}

