#include <bits/stdc++.h>
using namespace std;

int main() {
    const int N = 100;
    bitset<N> a, b;
    a.set(3); a.set(10); a.set(64);
    b[10] = 1; b[50] = 1;
    cout << a.count() << ' ' << (a & b).count() << ' ' << (a | b).count() << '\n';   // 3 1 4
    for (size_t i = a._Find_first(); i < N; i = a._Find_next(i)) cout << i << ' ';  // 3 10 64
    cout << '\n';
    a.flip(3);                                // bity: 10, 64
    a <<= 1;                                  // bity: 11, 65
    cout << a.test(11) << a[65] << a.any() << a.none() << '\n';   // 1110
    bitset<8> c(0b1011);
    cout << c << ' ' << c.to_ullong() << ' ' << c.to_string('.', '#') << '\n';   // 00001011 11 ....#.##
    bitset<8> d("1100");
    cout << (c ^ d) << ' ' << (~c).count() << ' ' << c.all() << '\n';   // 00000111 5 0

    bitset<1001> dp;                          // plecak: osiągalne sumy
    dp[0] = 1;
    for (int w : {3, 5, 7}) dp |= dp << w;
    cout << dp[8] << dp[9] << dp[15] << dp[11] << '\n';           // 1010
}

